import {APPAREL_COLOURS} from './apparel-colours.mjs';
import {GARMENTS} from './apparel-data.mjs';
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export const garmentPhoto=(id,colour=0,side='front')=>'/api/apparel/photo?'+new URLSearchParams({product:id,colour:String(colour),side});
export function garmentSwatches(rule,values,attribute='data-rf'){const f=rule.fields.find(f=>f.key==='colour');if(!f)return '';return `<fieldset class="garment-colours"><legend>Colour <b data-selected-colour>${esc(f.options.find(o=>o.value===values.colour)?.label)}</b></legend><div class="garment-swatches">${f.options.map((o,i)=>`<label title="${esc(o.label)}"><input type="radio" name="garment-colour" ${attribute}="colour" data-option-index="${i}" value="${o.value}" aria-label="${esc(o.label)}" ${o.value===values.colour?'checked':''}><span style="--swatch:${APPAREL_COLOURS[rule.id]?.[i]||'#888888'}" aria-hidden="true"></span></label>`).join('')}</div></fieldset>`;}
export function garmentSizes(rule,values,attribute='data-rf'){return `<fieldset class="garment-sizes"><legend>Sizes & quantities</legend><div class="garment-size-grid">${rule.fields.filter(f=>rule.quantityKeys?.includes(f.key)).map(f=>`<label><span>${esc(f.label.replace(/ · quantity$/,''))}</span><input type="number" ${attribute}="${f.key}" value="${values[f.key]??f.default}" min="${f.min}" max="${f.max}" step="${f.step}" aria-label="${esc(f.label)}"></label>`).join('')}</div><p class="small">Choose the quantity for each size.</p></fieldset>`;}

/* ---------- Apparel product page (gallery, colour swatches, size × quantity table, tabs) ----------
   Styles live in /apparel-product.css, loaded on demand by ensureApparelCSS(). Prices are never computed here:
   every amount shown comes from POST /api/rules/quote (server-authoritative price rules). */
const GROUPS={men:"Men's",women:"Women's",youth:'Kids & youth',hats:'Headwear',totes:'Totes'};
const CATEGORIES={'t-shirts':'T-shirts','long-sleeves':'Long sleeves',hoodies:'Hoodies',sweatshirts:'Sweatshirts',tanks:'Tanks',polos:'Polos',workwear:'Workwear',hats:'Hats',totes:'Totes'};
const CATEGORY_PAGES=['t-shirts','hoodies','sweatshirts','hats','workwear'];
const sizeName=f=>String(f.label).replace(/ · quantity$/,'');
const money=c=>new Intl.NumberFormat('en-CA',{style:'currency',currency:'CAD'}).format(c/100);
const garmentOf=id=>GARMENTS.find(g=>g.id===id);
const localImages=p=>(p?.images||[]).filter(s=>typeof s==='string'&&s.startsWith('/')&&!s.startsWith('//'));
const styleCode=name=>String(name).match(/\|\s*([A-Z0-9-]+)\s*$/i)?.[1]||String(name).match(/\s-\s*([A-Z0-9]+)\s*$/i)?.[1]||'';
const sec=(body,cls='')=>`<section class="sec ${cls}"><div class="wrap">${body}</div></section>`;
export function ensureApparelCSS(){if(typeof document==='undefined'||document.querySelector('link[data-apparel-css]'))return;const l=document.createElement('link');l.rel='stylesheet';l.href='/apparel-product.css';l.dataset.apparelCss='';document.head.append(l);}

/** Business-day estimate (production 7 business days, weekends skipped). Display only. */
export function readyDate(from=new Date(),days=7){const d=new Date(from);let n=0;while(n<days){d.setDate(d.getDate()+1);if(d.getDay()!==0&&d.getDay()!==6)n++;}return d;}

function crumbs(p){const g=p.group,c=p.category;const cHref=CATEGORY_PAGES.includes(c)&&c!=='hats'?`/satin/apparel/${c}/?group=${g}`:`/satin/apparel/?group=${g}&category=${c}`;return `<nav class="ap-crumbs" aria-label="Breadcrumb"><ol><li><a href="/satin/">Home</a></li><li><a href="/satin/apparel/">Apparel</a></li>${GROUPS[g]?`<li><a href="/satin/apparel/?group=${esc(g)}">${esc(GROUPS[g])}</a></li>`:''}${CATEGORIES[c]&&!['hats','totes'].includes(c)?`<li><a href="${esc(cHref)}">${esc(CATEGORIES[c])}</a></li>`:''}<li aria-current="page">${esc(p.name)}</li></ol></nav>`;}

function galleryHTML(p){const id=p.ruleId,g=garmentOf(id),colour=g?.colors?.[0]||'';const extra=localImages(p);const views=[['front','Front'],['back','Back'],...extra.map((src,i)=>['photo:'+i,'Model photo'])];
return `<div class="ap-gallery" data-ap-gallery data-rule="${esc(id)}" data-colour="0" data-view="front" data-name="${esc(p.name)}">
<div class="ap-stage"><button type="button" class="ap-zoom" data-ap-zoom aria-label="Zoom photo"><img data-ap-main src="${esc(garmentPhoto(id,0,'front'))}" alt="${esc(p.name)} · ${esc(colour)} · front" width="600" height="600"></button>
<button type="button" class="ap-nav ap-prev" data-ap-step="-1" aria-label="Previous photo"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="M15 5l-7 7 7 7"/></svg></button><button type="button" class="ap-nav ap-next" data-ap-step="1" aria-label="Next photo"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="M9 5l7 7-7 7"/></svg></button>
<span class="ap-zoom-hint" aria-hidden="true"><svg viewBox="0 0 24 24"><circle cx="11" cy="11" r="6.5"/><path d="M16 16l4.5 4.5M11 8v6M8 11h6"/></svg></span></div>
<div class="ap-thumbs">${views.map(([v,label],i)=>`<button type="button" data-ap-thumb="${v}" aria-pressed="${i===0}" aria-label="${esc(label)}"><img src="${esc(v==='front'||v==='back'?garmentPhoto(id,0,v):extra[Number(v.slice(6))])}" alt="" loading="lazy" width="96" height="96"></button>`).join('')}</div>
<p class="ap-gallery-note">Showing <b data-ap-colour-name>${esc(colour)}</b>. Your colour and print placement are confirmed in a proof before production.</p></div>`;}

const SIZE_GUIDE={men:[['S','34–36'],['M','38–40'],['L','42–44'],['XL','46–48'],['2XL','50–52'],['3XL','54–56'],['4XL','58–60'],['5XL','62–64']],women:[['XS','30–32'],['S','32–34'],['M','34–36'],['L','36–38'],['XL','40–42'],['2XL','44–46'],['3XL','46–48']],youth:[['XS','26–28'],['S','28–30'],['M','30–32'],['L','32–34'],['XL','34–36']]};
function tabsHTML(p){const g=garmentOf(p.ruleId)||{},hats=p.group==='hats',totes=p.group==='totes';const sizes=g.sizeOptions||[];const guide=SIZE_GUIDE[p.group==='women'?'women':p.group==='youth'?'youth':'men'].filter(([s])=>!sizes.length||sizes.includes(s));
const details=String(p.details||'').split('\n').filter(l=>l&&!/^Product:/.test(l));
const panels=[['Details',`<div class="ap-tab-grid"><div><h3>About this ${hats?'cap':totes?'tote':'garment'}</h3><p>${esc(p.description||'')}</p><ul>${details.map(l=>`<li>${esc(l)}</li>`).join('')}${g.colors?.length?`<li>${g.colors.length} colour${g.colors.length>1?'s':''} available</li>`:''}${styleCode(p.name)?`<li>Style code ${esc(styleCode(p.name))}</li>`:''}</ul></div><div><h3>Decoration</h3><ul><li>DTF (direct-to-film): full colour, photos and gradients, soft hand-feel.</li><li>Vinyl heat press: solid colours, names and numbers.</li>${hats||p.category==='polos'?'<li>Embroidery available for this style.</li>':''}<li>No minimum order · 5% off orders above 20 pieces.</li></ul></div></div>`],
['Sizing chart',hats?'<p>Most caps are one size with an adjustable snap or strap closure. Fitted styles list their size range in the size table above.</p>':totes?'<p>Totes are one size. Ask us for exact bag dimensions for your style.</p>':`<p>Approximate body chest measurements (inches) for a typical ${p.group==='women'?"women's":p.group==='youth'?'youth':'adult unisex'} fit. Sizing varies by style, so ask us for the exact manufacturer spec sheet if fit is critical.</p><div class="ap-chart-wrap"><table class="ap-chart"><thead><tr><th scope="row">Size</th>${guide.map(([s])=>`<th scope="col">${s}</th>`).join('')}</tr></thead><tbody><tr><th scope="row">Chest (in)</th>${guide.map(([,c])=>`<td>${c}</td>`).join('')}</tr></tbody></table></div><p class="small">How to measure: wrap the tape under the arms around the fullest part of the chest. Available sizes for this style: ${esc(g.sizes||sizes.join(', '))}.</p>`],
['File prep','<ol class="ap-steps"><li><b>Send your logo in high quality.</b> Vector (SVG, PDF, AI saved as PDF) or a transparent PNG at 300 DPI at the printed size.</li><li><b>Show the placement.</b> A photo, screenshot or sketch of where the logo goes and roughly how big (e.g. left chest 3.5 in, full back 11 in).</li><li><b>Approve the proof.</b> We send a proof with the print sized in inches on your garment colour before anything is printed.</li></ol><p class="small">Low-resolution files may print blurry. Need help? Choose “I need a designer” or create your design in Design Studio.</p>'],
['Care instructions','<ul><li>Wait 24 hours before the first wash.</li><li>Wash inside out in cold water with mild detergent; no bleach or fabric softener.</li><li>Tumble dry low or hang dry.</li><li>Do not iron directly on the print; do not dry-clean.</li></ul>']];
return `<div class="ap-tabs" data-ap-tabs><div class="ap-tablist" role="tablist" aria-label="Product information">${panels.map(([n],i)=>`<button type="button" role="tab" id="ap-tab-${i}" aria-controls="ap-panel-${i}" aria-selected="${i===0}" tabindex="${i===0?0:-1}">${n}</button>`).join('')}</div>${panels.map(([n,b],i)=>`<div class="ap-panel" role="tabpanel" id="ap-panel-${i}" aria-labelledby="ap-tab-${i}" ${i?'hidden':''}>${b}</div>`).join('')}</div>`;}

function productCard(p){return `<a class="ap-card" href="${esc(p.path)}/"><span class="ap-card-img"><img src="${esc(garmentPhoto(p.ruleId,0))}" alt="${esc(p.name)}" loading="lazy" width="300" height="300"></span><span class="ap-card-name">${esc(p.name)}</span><span class="ap-card-meta">${esc(GROUPS[p.group]||p.group)} · ${esc(CATEGORIES[p.category]||p.category)}</span></a>`;}
function carouselHTML(title,items,label){return `<div class="ap-carousel" data-ap-carousel><div class="ap-carousel-top"><h2 class="ap-h2">${esc(title)}</h2><div class="ap-carousel-nav"><button type="button" data-ap-scroll="-1" aria-label="Previous">‹</button><button type="button" data-ap-scroll="1" aria-label="Next">›</button></div></div><div class="ap-track" tabindex="0" aria-label="${esc(label)}">${items.map(productCard).join('')}</div></div>`;}

/** Full page HTML for /satin/apparel/products/<model>. The pricing form (calculator) replaces the .cfg placeholder. */
export function apparelProductPage(p,list=[]){const g=garmentOf(p.ruleId)||{};const code=styleCode(p.name);
const related=[...list.filter(x=>x.id!==p.id&&x.group===p.group&&x.category===p.category),...list.filter(x=>x.id!==p.id&&x.group===p.group&&x.category!==p.category),...list.filter(x=>x.id!==p.id&&x.group!==p.group&&x.category===p.category)].slice(0,10);
const head=`${crumbs(p)}<div class="ap-product" data-apparel-product="${esc(p.ruleId)}">${galleryHTML(p)}<div class="ap-info"><span class="eyebrow">${esc(GROUPS[p.group]||p.group)} · ${esc(CATEGORIES[p.category]||p.category)}</span><h1 class="ap-title">${esc(p.name)}</h1><p class="ap-meta">${[code&&'Style '+code,g.sizes&&(/one size/i.test(g.sizes)?'One size':'Sizes '+g.sizes),g.colors?.length&&g.colors.length+' colours'].filter(Boolean).map(esc).join(' · ')}</p><p class="ap-lede">Your brand on a ${esc((CATEGORIES[p.category]||'garment').toLowerCase().replace(/s$/,''))} you choose. Pick a colour, enter quantities by size, then upload your logo or create it in Design Studio. No minimum order.</p><div class="apparel-benefits ap-benefits"><span>No minimum order</span><span>21+ pieces · 5% off</span><span>DTF · Vinyl heat press${p.category==='polos'||p.group==='hats'?' · Embroidery':''}</span></div><div class="cfg"></div></div></div>`;
return sec(head,'ap-sec')+sec(tabsHTML(p),'ap-sec ap-sec-tabs')+(related.length?sec(carouselHTML('Customers also bought',related,'More garments; scroll to see more'),'ap-sec ap-sec-related'):'');}

/** Extra blocks for the /satin/apparel landing page: popular models + shop-by-category cards (filter buttons). */
const POPULAR=['apparel-men-g500','apparel-men-g640','apparel-women-g500l','apparel-men-3001c','apparel-men-g185','apparel-youth-g500b','apparel-men-g180','apparel-hats-6606','apparel-men-7006','apparel-totes-q-tees-q800','apparel-women-6405','apparel-men-980'];
export function apparelLanding(list){const pop=POPULAR.map(id=>list.find(p=>p.ruleId===id)).filter(Boolean);
const cats=[['men',"Men's clothing",'/apparel/official/G500-aquatic-official-model.jpeg'],['women',"Women's clothing",'/apparel/official/G500L-coral-silk-official-model.jpeg'],['youth','Kids & youth','/apparel/official/G500B-white-official-model.jpeg'],['totes','Totes',garmentPhoto('apparel-totes-q-tees-q800',0)],['hats','Headwear',garmentPhoto('apparel-hats-6606',0)]].filter(([g])=>list.some(p=>p.group===g));
return {popular:pop.length?carouselHTML('Most popular',pop,'Popular garments; scroll to see more'):'',categories:`<div class="ap-cat-cards"><h2 class="ap-h2">Shop by category</h2><div class="ap-cat-grid">${cats.map(([g,n,img])=>`<button type="button" class="ap-cat" data-apparel-k="group" data-apparel-v="${g}" data-ap-jump><span class="ap-cat-img"><img src="${esc(img)}" alt="" loading="lazy"></span><span class="ap-cat-name">${esc(n)}</span><span class="ap-cat-link">Shop now →</span></button>`).join('')}</div></div>`};}

/** Inner HTML of the pricing box (div.rule-cfg) for apparel rules (rules with quantityKeys). Keeps every data-* hook the calculator uses. */
export function apparelConfigMarkup(rule,configured,values,product,artwork=''){const colour=rule.fields.find(f=>f.key==='colour'),qty=rule.fields.filter(f=>rule.quantityKeys.includes(f.key));const hex=APPAREL_COLOURS[rule.id]||[];
const pills=f=>`<fieldset class="ap-option"><legend>${esc(f.label)}</legend><div class="ap-pills">${f.options.map((o,i)=>`<label><input type="radio" name="option-${f.key}" data-rf="${f.key}" data-option-index="${i}" value="${o.value}" ${o.value===values[f.key]?'checked':''}><span>${esc(o.label)}</span></label>`).join('')}</div></fieldset>`;
// Print locations: rules with loc_* checkboxes (placement = "Choose locations") show a multi-select; the legacy single
// placement choice stays hidden but valid for carts created before.
const locs=rule.fields.filter(f=>f.type==='checkbox'&&/^loc_/.test(f.key)),multi=locs.length&&rule.fields.some(f=>f.key==='placement'&&f.options.some(o=>/choose locations/i.test(o.label)));
const locHTML=multi?`<fieldset class="ap-option ap-locations" data-ap-locations><legend>Print locations <small>Choose one or more</small></legend><div class="ap-pills ap-pills-multi">${locs.map(f=>`<label><input type="checkbox" data-rf="${f.key}" ${values[f.key]?'checked':''}><span>${esc(f.label)}</span></label>`).join('')}</div><p class="small ap-loc-note" data-ap-loc-note>The first location is included in the price per piece; each extra location adds its print cost.</p></fieldset>`:'';
// Hats print on the front only: no placement choice (old carts keep their saved value).
const hat=/^apparel-hats-/.test(rule.id);
const others=rule.fields.filter(f=>f.key!=='colour'&&f.key!=='design'&&!rule.quantityKeys.includes(f.key)&&!((multi||hat)&&(f.key==='placement'||locs.includes(f))));
const total=qty.reduce((n,f)=>n+(Number(values[f.key])||0),0);
return `<div class="ap-config"><div class="rule-fields ap-fields">${colour?`<fieldset class="ap-colours"><legend><span class="ap-colon">Colour</span> <b data-selected-colour>${esc(colour.options.find(o=>o.value===values.colour)?.label)}</b></legend><div class="ap-swatches">${colour.options.map((o,i)=>{const c=hex[i]||'#888888';return `<label title="${esc(o.label)}"><input type="radio" name="garment-colour" data-rf="colour" data-option-index="${i}" value="${o.value}" aria-label="${esc(o.label)}" ${o.value===values.colour?'checked':''}><span style="--swatch:${c}" ${/^#f[0-9a-f]f[0-9a-f]f[0-9a-f]$|^#fff/i.test(c)?'data-light':''} aria-hidden="true"></span></label>`;}).join('')}</div></fieldset>`:''}
<fieldset class="ap-sizes"><legend>Sizes & quantities</legend><div class="ap-size-table" data-count="${qty.length}"><div class="ap-size-head" aria-hidden="true"><span>Size</span><span>Quantity</span><span>Price per piece</span></div>${qty.map(f=>`<label class="ap-size"><span class="ap-size-name">${esc(sizeName(f))}</span><input type="number" inputmode="numeric" data-rf="${f.key}" min="${f.min}" max="${f.max}" step="${f.step}" value="${Number(values[f.key])?values[f.key]:''}" placeholder="0" aria-label="${esc(sizeName(f))} quantity"><span class="ap-unit" data-ap-unit="${f.key}">—</span></label>`).join('')}</div><p class="ap-size-foot"><b data-ap-qty-total>${total} piece${total===1?'':'s'}</b><span>${hat?'Price per piece includes printing on the front.':`Price per piece includes printing for the selected ${multi?'print locations':'placement'}.`}</span></p></fieldset>
${locHTML}${others.map(f=>f.type==='select'?pills(f):f.type==='checkbox'?`<label class="product-check-card"><input type="checkbox" data-rf="${f.key}" ${values[f.key]?'checked':''}><span>${esc(f.label)}</span></label>`:`<label class="ap-number"><span>${esc(f.label)}</span><input type="number" data-rf="${f.key}" min="${f.min}" max="${f.max}" step="${f.step}" value="${values[f.key]}"></label>`).join('')}
<div class="ap-turnaround"><span class="ap-label">Turnaround</span><p><b>Standard · 5–7 business days</b></p><p>Order today and it is estimated to be ready by <b data-ap-ready>${esc(readyDate().toLocaleDateString('en-CA',{weekday:'long',month:'short',day:'numeric'}))}</b>.</p><p class="tiny">Estimate only. Production starts after proof approval; need it sooner? Ask us about rush.</p></div></div>${artwork}</div>
<aside class="rule-summary ap-summary"><div class="ap-total"><span class="ap-total-label">Total cost<small>Garment + printing</small></span><div class="product-order-total" data-order-total></div></div><div class="studio-price" data-rule-price>Calculating…</div><p data-price-error role="status"></p><div class="ap-actions"><button type="button" class="btn ghost" data-ap-design>Create / upload design</button><button class="btn" data-rule-add>Add to cart</button></div><button class="btn ghost block ap-quote" data-quote="Apparel">Get exact quote</button><details class="ap-more"><summary>Your selections, notes &amp; discount code</summary><div class="product-order-choices" data-order-choices></div><label class="order-notes">Project notes <em>(optional)</em><textarea data-order-notes maxlength="1000" rows="3" placeholder="Deadline, colours, placement or anything we should know"></textarea></label><label>Discount code<input data-discount-code maxlength="40" placeholder="Optional code"></label><button class="btn ghost sm" data-apply-code>Apply code</button></details>${rule.priceNote?`<p class="small product-price-note">${esc(rule.priceNote)}</p>`:''}</aside>`;}

/* ---------- browser behaviour ---------- */
function galleryViews(gallery){return [...gallery.querySelectorAll('[data-ap-thumb]')].map(b=>b.dataset.apThumb);}
function showView(gallery,view){const main=gallery.querySelector('[data-ap-main]'),thumb=gallery.querySelector(`[data-ap-thumb="${view}"]`);if(!main||!thumb)return;gallery.dataset.view=view;gallery.querySelectorAll('[data-ap-thumb]').forEach(b=>b.setAttribute('aria-pressed',String(b===thumb)));const src=view==='front'||view==='back'?garmentPhoto(gallery.dataset.rule,gallery.dataset.colour,view):thumb.querySelector('img').getAttribute('src');if(main.getAttribute('src')!==src)main.src=src;const name=gallery.querySelector('[data-ap-colour-name]')?.textContent||'';main.alt=`${gallery.dataset.name}${view==='front'||view==='back'?' · '+name+' · '+view:' · model photo'}`;gallery.querySelector('.ap-stage')?.classList.remove('is-zoomed');}
export function setGalleryColour(gallery,colour,label){if(!gallery)return;gallery.dataset.colour=String(colour);for(const side of ['front','back']){const img=gallery.querySelector(`[data-ap-thumb="${side}"] img`);if(img)img.src=garmentPhoto(gallery.dataset.rule,colour,side);}const n=gallery.querySelector('[data-ap-colour-name]');if(n&&label)n.textContent=label;const v=gallery.dataset.view||'front';showView(gallery,v==='front'||v==='back'?v:'front');}
function mountGallery(gallery){if(gallery._apMounted)return;gallery._apMounted=true;const main=gallery.querySelector('[data-ap-main]'),stage=gallery.querySelector('.ap-stage');
gallery.addEventListener('click',e=>{const t=e.target.closest('[data-ap-thumb]');if(t){showView(gallery,t.dataset.apThumb);return;}const s=e.target.closest('[data-ap-step]');if(s){const v=galleryViews(gallery),i=v.indexOf(gallery.dataset.view);showView(gallery,v[(i+Number(s.dataset.apStep)+v.length)%v.length]);return;}const z=e.target.closest('[data-ap-zoom]');if(z){const r=z.getBoundingClientRect();main.style.transformOrigin=`${((e.clientX-r.left)/r.width*100)||50}% ${((e.clientY-r.top)/r.height*100)||50}%`;stage.classList.toggle('is-zoomed');}});
stage.addEventListener('mousemove',e=>{if(!stage.classList.contains('is-zoomed'))return;const r=stage.getBoundingClientRect();main.style.transformOrigin=`${(e.clientX-r.left)/r.width*100}% ${(e.clientY-r.top)/r.height*100}%`;});
stage.addEventListener('mouseleave',()=>stage.classList.remove('is-zoomed'));
gallery.addEventListener('keydown',e=>{if(e.key!=='ArrowLeft'&&e.key!=='ArrowRight')return;if(!e.target.closest('[data-ap-thumb],[data-ap-zoom],[data-ap-step]'))return;const v=galleryViews(gallery),i=v.indexOf(gallery.dataset.view);showView(gallery,v[(i+(e.key==='ArrowRight'?1:-1)+v.length)%v.length]);});
/* Photo fallback: if a colour photo is missing, show the first available model photo instead of a broken image. */
main.addEventListener('error',()=>{const alt=gallery.querySelector('[data-ap-thumb^="photo:"] img');if(alt&&main.getAttribute('src')!==alt.getAttribute('src'))main.src=alt.getAttribute('src');});
gallery.querySelectorAll('[data-ap-thumb] img').forEach(img=>img.addEventListener('error',()=>{img.closest('button').hidden=true;},{once:true}));}
function mountTabs(tabs){if(tabs._apMounted)return;tabs._apMounted=true;const list=[...tabs.querySelectorAll('[role=tab]')];const select=t=>{list.forEach(b=>{const on=b===t;b.setAttribute('aria-selected',String(on));b.tabIndex=on?0:-1;tabs.querySelector('#'+b.getAttribute('aria-controls')).hidden=!on;});};tabs.addEventListener('click',e=>{const t=e.target.closest('[role=tab]');if(t)select(t);});tabs.addEventListener('keydown',e=>{const i=list.indexOf(document.activeElement);if(i<0||!['ArrowLeft','ArrowRight','Home','End'].includes(e.key))return;e.preventDefault();const n=e.key==='Home'?0:e.key==='End'?list.length-1:(i+(e.key==='ArrowRight'?1:-1)+list.length)%list.length;list[n].focus();select(list[n]);});}
function mountCarousel(c){if(c._apMounted)return;c._apMounted=true;const track=c.querySelector('.ap-track');c.addEventListener('click',e=>{const b=e.target.closest('[data-ap-scroll]');if(b)track.scrollBy({left:Number(b.dataset.apScroll)*track.clientWidth*.9,behavior:'smooth'});});}

/** Page-level behaviour for /satin/apparel/*: gallery, tabs, carousels and category cards. Safe to call repeatedly. */
export function mountApparelPage(root){if(!root?.querySelector)return;if(root.querySelector('[data-ap-gallery],[data-ap-tabs],[data-ap-carousel],.ap-cat-cards'))ensureApparelCSS();root.querySelectorAll('[data-ap-gallery]').forEach(mountGallery);root.querySelectorAll('[data-ap-tabs]').forEach(mountTabs);root.querySelectorAll('[data-ap-carousel]').forEach(mountCarousel);
root.querySelectorAll('[data-ap-jump]').forEach(b=>{if(b._apJump)return;b._apJump=true;b.addEventListener('click',()=>setTimeout(()=>root.querySelector('[data-apparel-count]')?.scrollIntoView({behavior:'smooth',block:'start'}),0));});}

/** Behaviour of the apparel pricing box once the calculator has mounted it. getValues() returns the calculator's live values. */
export function mountApparelProduct(box,rule,configured,getValues){if(!box?.isConnected||!rule?.quantityKeys||box._apMounted)return;box._apMounted=true;ensureApparelCSS();
const root=box.closest('.ap-product')||document,gallery=root.querySelector('[data-ap-gallery]');if(gallery)mountGallery(gallery);
const colourField=rule.fields.find(f=>f.key==='colour');const colourLabel=v=>colourField?.options.find(o=>o.value===v)?.label||'';
const totalQty=()=>{const v=getValues();return rule.quantityKeys.reduce((n,k)=>n+(Number(v[k])||0),0);};
const syncColour=()=>setGalleryColour(gallery,getValues().colour??0,colourLabel(getValues().colour));
const cache=new Map();let timer=0,serial=0;
async function unitPrices(){const version=++serial,v=getValues(),n=Math.max(totalQty(),1);const cells=[...box.querySelectorAll('[data-ap-unit]')];
await Promise.all(cells.map(async cell=>{const key=cell.dataset.apUnit,values={...v,design:0};for(const k of rule.quantityKeys)values[k]=0;values[key]=n;const id=JSON.stringify(values);try{if(!cache.has(id))cache.set(id,fetch('/api/rules/quote',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({id:rule.id,values})}).then(r=>r.ok?r.json():Promise.reject()).then(d=>d.quote));const q=await cache.get(id);if(version!==serial)return;cell.textContent=q.subtotal>0?money(Math.round(q.subtotal/n)):(rule.priceOnRequest?'On request':'—');cell.title=q.subtotal>0?`${money(Math.round(q.subtotal/n))} each at ${n} piece${n===1?'':'s'}, before tax`:'';}catch{cache.delete(id);if(version===serial)cell.textContent='—';}}));}
const refresh=()=>{const n=totalQty(),t=box.querySelector('[data-ap-qty-total]');if(t)t.textContent=`${n} piece${n===1?'':'s'}`;clearTimeout(timer);timer=setTimeout(unitPrices,250);};
box.addEventListener('change',e=>{if(e.target.dataset?.rf==='colour')syncColour();if(e.target.dataset?.rf)refresh();});
box.addEventListener('input',e=>{if(e.target.dataset?.rf&&rule.quantityKeys.includes(e.target.dataset.rf))refresh();});
/* No garments → no cart line. Runs in the capture phase, before the calculator's Add to cart handler. */
box.addEventListener('click',e=>{if(!e.target.closest('[data-rule-add]')||totalQty()>0)return;e.preventDefault();e.stopPropagation();const err=box.querySelector('[data-price-error]');if(err)err.textContent='Enter a quantity for at least one size.';box.querySelector('[data-ap-unit]')?.closest('label')?.querySelector('input')?.focus();},true);
/* Per-size breakdown travels with the cart line. */
const terms=box._terms;box._terms=()=>{const list=terms?terms():[];const v=getValues(),parts=rule.fields.filter(f=>rule.quantityKeys.includes(f.key)&&Number(v[f.key])>0).map(f=>`${sizeName(f)} × ${v[f.key]}`);return parts.length?[...list,'Sizes: '+parts.join(' · ')]:list;};
/* Create / upload design → Design Studio for this garment (studio mode of the artwork section). */
box.querySelector('[data-ap-design]')?.addEventListener('click',()=>{const radio=box.querySelector('[name="artwork-mode"][value="studio"]');if(radio){radio.checked=true;radio.dispatchEvent(new Event('change',{bubbles:true}));const link=box.querySelector('[data-studio-link]');if(link?.href){location.assign(link.href);return;}}box.querySelector('.rule-artwork')?.scrollIntoView({behavior:'smooth',block:'start'});});
const ready=box.querySelector('[data-ap-ready]');if(ready)ready.textContent=readyDate().toLocaleDateString(document.documentElement.lang||'en-CA',{weekday:'long',month:'short',day:'numeric'});
syncColour();unitPrices();}
